      trace.push("push:get");
      // 到原追加 callee 点才装故障，避免 scope 的早政策读取先抛错，冒成已付条目构造失败。
      Object.defineProperty(ability.state, "protectionPolicy", { get() { trace.push("policy:get"); throw failure; } });
