  test(`${change}: a stale Mirror response cannot consume, report or close a new scope`, async () => {
    const game = fixture(),
      events: GameEvent[] = [],
      ability = native(game);
    let current = true,
      calls = 0;
    const ctx = context(
      game,
      events,
      async () => {
